    """
    Uses the Bellman-Ford algorithm to find the shortest path in a weighted directed graph.
    Returns the shortest distance and the path as a list of node names.
    """
    # Initialize distances and predecessors
    distances = {node: float('inf') for node in graph}
    predecessors = {node: None for node in graph}
    distances[start] = 0

    # Relax edges up to |V| - 1 times
    vertices = list(graph.keys())
    vertex_count = len(vertices)

    for _ in range(vertex_count - 1):
        for node in vertices:
            for neighbor, weight in graph[node]:
                if distances[node] != float('inf') and distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessors[neighbor] = node

    # Check for negative-weight cycles (not needed for the shortest path but good practice)
    for node in vertices:
        for neighbor, weight in graph[node]:
            if distances[node] != float('inf') and distances[node] + weight < distances[neighbor]:
                return float('inf'), []

    # Reconstruct the path from start to end
    path = []
    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = predecessors[current_node]

